"""Offline translations for the SPRT review. Run after the catalog collectors."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];folder=ROOT/'locales'
M={}
def add(key,translations):
    values=translations.split('|');assert len(values)==7,key;M[key]=values
